def calculate_flight_change_cost(reservation_id: str, cabin: str, flights: list):
    """
    Compute the EXACT amount the user will be charged (or refunded) by update_reservation_flights,
    WITHOUT changing anything. Call this BEFORE you tell the user the price of a flight change or a
    cabin change (upgrade), and quote the "user_will_pay" value it returns. Do not compute the price yourself.

    How the price works (the tool applies this for you):
    - The cabin applies to EVERY flight of the reservation. When the cabin changes, ALL flights,
      including the return flights you are not changing, are re-priced at the new cabin's current price.
    - A flight is kept at its old price only if the flight number, date AND cabin are all unchanged.
    - Charge = (sum of new prices x passengers) - (sum of old prices x passengers). A negative value is a refund.

    Cabin-only change (upgrade): copy the reservation's CURRENT flights from get_reservation_details.
    Example: get_reservation_details shows flights [<flight A> on <date A>, <flight B> on <date B>]; to quote business:
        calculate_flight_change_cost(reservation_id="<that reservation id>", cabin="business",
            flights=[{"flight_number": "<flight A>", "date": "<date A>"}, {"flight_number": "<flight B>", "date": "<date B>"}])
    Never invent flight numbers.
    BASIC ECONOMY CAN BE UPGRADED: a basic_economy reservation may change its cabin to economy or business
    (keep its current flights). Only its flights cannot change. Never tell the user a basic economy
    reservation cannot be upgraded - quote the upgrade with this tool instead.

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        cabin: The cabin for the WHOLE reservation after the change: 'basic_economy', 'economy' or 'business'.
        flights: The ENTIRE new list of flights (same list you will pass to update_reservation_flights), each {"flight_number": "<from the reservation or a search>", "date": "YYYY-MM-DD"}, including unchanged flights.

    Returns:
        A dict with per-flight old/new prices, passenger count, old_total, new_total and user_will_pay
        (positive = the user pays this amount, negative = refund), or an "Error: ..." string.
    """
    def _d(x):
        if hasattr(x, "model_dump"):
            return x.model_dump()
        return dict(x)

    res = env_get_reservation_details(reservation_id=reservation_id)
    if not isinstance(res, dict):
        return res
    flights = [_d(f) for f in flights]
    n = len(res.get("passengers") or [])
    old_flights = res.get("flights") or []
    old_cabin = res.get("cabin")

    cur_keys = «redacted» f["date"]) for f in old_flights]
    if old_cabin == "basic_economy" and [(f.get("flight_number"), f.get("date")) for f in flights] != cur_keys:
        «redacted» ("Error: reservation " + reservation_id + " is basic economy; its flights cannot be changed, only its cabin. "
                "For a cabin-only change quote exactly the current flights: " +
                ", ".join(f["flight_number"] + " " + f["origin"] + "->" + f["destination"] + " " + f["date"] for f in old_flights) +
                ". If the user wants different flights, tell them basic economy flights cannot be modified.")

    # flight_number -> route, from the reservation itself
    routes = {}
    for f in old_flights:
        routes[f["flight_number"]] = (f["origin"], f["destination"])

    cache = {}

    def _lookup(fn, date):
        # find this flight on this date in the search results (gives price + seats)
        cands = []
        if fn in routes:
            cands.append(routes[fn])
        o, d = res.get("origin"), res.get("destination")
        for pair in ((o, d), (d, o)):
            if pair not in cands:
                cands.append(pair)
        for (a, b) in cands:
            key = «redacted» a, b, date)
            if key not in cache:
                cache[key] = env_search_direct_flight(origin=a, destination=b, date=date)
            r = cache[key]
            if isinstance(r, list):
                for x in r:
                    if x.get("flight_number") == fn:
                        return x
        for (a, b) in ((o, d), (d, o)):
            for dd in (date,):
                key = «redacted» a, b, dd)
                if key not in cache:
                    cache[key] = env_search_onestop_flight(origin=a, destination=b, date=dd)
                r = cache[key]
                if isinstance(r, list):
                    for p in r:
                        for x in p:
                            if x.get("flight_number") == fn and (x.get("date") in (None, date)):
                                return x
            # second leg of a one-stop may start the day before
            key = «redacted» a, b, date)
            if key not in cache:
                try:
                    y, m, dday = date.split("-")
                    prev = "%s-%s-%02d" % (y, m, int(dday) - 1)
                    cache[key] = env_search_onestop_flight(origin=a, destination=b, date=prev)
                except Exception:
                    cache[key] = None
            r = cache[key]
            if isinstance(r, list):
                for p in r:
                    for x in p:
                        if x.get("flight_number") == fn and x.get("date") == date:
                            return x
        return None

    rows = []
    new_total = 0
    for f in flights:
        fn, date = f.get("flight_number"), f.get("date")
        kept = next((of for of in old_flights
                     if of["flight_number"] == fn and of["date"] == date and cabin == old_cabin), None)
        if kept:
            rows.append({"flight_number": fn, "date": date, "price_per_passenger": kept["price"], "note": "unchanged (keeps old price)"})
            new_total += kept["price"] * n
            continue
        info = _lookup(fn, date)
        if info is None:
            cur = ", ".join(of["flight_number"] + " on " + of["date"] for of in old_flights)
            st = env_get_flight_status(flight_number=fn, date=date)
            if isinstance(st, str) and st in ("landed", "flying"):
                return ("Error: flight " + str(fn) + " on " + str(date) + " has already been flown (status: " + st +
                        "). A reservation with a flown flight cannot be changed or upgraded. Tell the user this.")
            return ("Error: flight " + str(fn) + " on " + str(date) + " was not found as an available flight. "
                    "This reservation's current flights are: " + cur + ". For a cabin-only upgrade pass exactly these. "
                    "For new flights copy the number and date from search_direct_flight / search_onestop_flight.")
        price = (info.get("prices") or {}).get(cabin)
        seats = (info.get("available_seats") or {}).get(cabin, 0)
        if price is None:
            return "Error: no " + str(cabin) + " price for flight " + str(fn) + " on " + str(date) + "."
        if seats < n:
            return ("Error: flight " + str(fn) + " on " + str(date) + " has only " + str(seats) + " " + str(cabin) +
                    " seats left but the reservation has " + str(n) + " passengers.")
        rows.append({"flight_number": fn, "date": date, "price_per_passenger": price, "note": "re-priced at current " + str(cabin) + " price"})
        new_total += price * n

    old_total = sum(f["price"] for f in old_flights) * n
    diff = new_total - old_total
    if diff > 0:
        msg = "The user will be charged $" + str(diff) + " in total for this change."
    elif diff < 0:
        msg = "The user will be refunded $" + str(-diff) + " in total for this change."
    else:
        msg = "This change costs $0."
    return {
        "reservation_id": reservation_id,
        "current_cabin": old_cabin,
        "new_cabin": cabin,
        "passengers": n,
        "flights": rows,
        "old_total": old_total,
        "new_total": new_total,
        "user_will_pay": diff,
        "summary": msg + " (Cabin " + str(cabin) + " applies to all " + str(len(rows)) + " flights.)",
    }
